from pathlib import Path
import collections,json
from pypdf import PdfReader
from openpyxl import load_workbook
p=Path('artifacts/runs/source-capture-20261014T100034Z/sources')
for name in ['initial-claim-binder.pdf','claim-updates-binder.pdf','receipt-binder.pdf']:
 r=PdfReader(p/name);print(name,'METADATA',r.metadata)
 for i in ([0] if name!='claim-updates-binder.pdf' else [0,1,6]):
  print('PAGE',i+1,r.pages[i].extract_text())
w=load_workbook(p/'travel-registers-workbook.xlsx',data_only=False,read_only=True)
print('WORKBOOK METADATA',w.properties)
for sh in w:
 print('TAB',sh.title,'STATE',sh.sheet_state)
 nonempty=[(n,row) for n,row in enumerate(sh.values,1) if any(v is not None for v in row)]
 print('NOTES/HEADERS',nonempty[:5], 'nonempty rows',len(nonempty))
 if sh.title in ('Review ledger','Finance activity','Travel cancellations'):
  headers=dict((v,i) for i,v in enumerate(nonempty[4][1]) if v is not None)
  # Retained workbook tables use physical row 5 as header.
  headers={v:i for i,v in enumerate(list(sh.values)[4]) if v is not None}
  batchcol=headers['Arrival batch'];batches=collections.Counter(row[batchcol] for n,row in nonempty if n>5)
  print('ARRIVAL COUNTS',dict(batches))
  for n,row in nonempty:
   if n>5 and (n<9 or row[batchcol]==4 or sh.title=='Travel cancellations'):
    print('ROW',n,dict((h,row[i]) for h,i in headers.items()))
